\label{tab:lambda}
\begin{tabular}{@{}rcccc@{}}
\toprule
$\lambda$ & IID & DD OOD & FITD OOD & AA OOD \\
\midrule
0 & 1.000 & 1.000 & 1.000 & 1.000 \\
